const gate = (check, next) => async (req, res) => {
  const id = await check(req);                  // this gate's own evidence
  if (!id) { res.statusCode = 403; res.end(); return; }   // fail closed
  req.identity = id;                            // hand identity inward
  return next(req, res);                        // delegate to the inner gate
};
app.use(gate(edgePolicy, gate(tenantPolicy, handler)));   // gates nest in order

