const gate = (target, authorize) => new Proxy(target, {
  get(obj, prop, receiver) {                    // every access crosses this gate
    authorize(prop);                            // throws on deny: fail closed
    const value = Reflect.get(obj, prop, receiver);
    return typeof value === 'function' ? value.bind(obj) : value;
  },
});
const service = gate(gate(rawService, tenantRule), edgeRule);   // gates nest
